// Cue record: logs each Latin call the owner gives on a PR, with the PR's state,
// so the final review before merge has it in one place. It only records:
// no model call, no review, no seal, no merge. Plan: docs/latin-workflow.md.
// Same idea as custos's latin-cue-record.yml; hodie reads cues with cue-parser.js
// and has no observation document.

const { parseComment } = require('./cue-parser.js');

const MARK = '<!-- hodie-latin-cue -->';
const LOG_START = '<!-- cue-log-start -->';
const LOG_END = '<!-- cue-log-end -->';
const ROW_RE = /^\| \d{12} /;
const SHA_RE = /`([0-9a-f]{7,40})`/;
const FAIL = ['failure', 'timed_out', 'cancelled', 'action_required'];

// The call(s) in one comment, as "Ultima Probatio · finalize". Empty when there is none.
function cueNames(body, authorType, association) {
  const read = parseComment(body, { authorType, association });
  return [...new Set(read.cues.map((c) => c.canonical))];
}

// UTC prima-clock stamp, YYYYMMDDHHMM.
function stamp(date) {
  return new Date(date).toISOString().replace(/[-:T]/g, '').slice(0, 12);
}

// The log rows already in the comment, oldest first.
function oldRows(body) {
  const text = body || '';
  const s = text.indexOf(LOG_START);
  const e = text.indexOf(LOG_END);
  if (s === -1 || e <= s) return [];
  return text.slice(s + LOG_START.length, e).split('\n').filter((l) => ROW_RE.test(l));
}

// The head commit named in the last row, or null.
function lastSha(rows) {
  const last = rows[rows.length - 1];
  return last ? (last.match(SHA_RE) || [])[1] || null : null;
}

function rowFor(call) {
  return `| ${stamp(call.at)} | ${call.cue} | @${call.by} | \`${call.head}\` | ${call.source} |`;
}

// How the checks on the head stand.
function tally(runs) {
  const done = runs.filter((r) => r.status === 'completed');
  return {
    failed: done.filter((r) => FAIL.includes(r.conclusion)),
    pending: runs.filter((r) => r.status !== 'completed'),
    passed: done.filter((r) => r.conclusion === 'success').length,
  };
}

const isReady = (pr, t, open) =>
  !pr.draft && !t.failed.length && !t.pending.length && !open && pr.mergeable_state === 'clean';

function stateLines(s) {
  const t = s.tally;
  return [
    `${isReady(s.pr, t, s.open) ? '✅' : '⬜'} Ready to verify for merge ` +
      '(not a draft, checks passed, no open threads, merges cleanly)',
    `- Draft: ${s.pr.draft ? 'yes' : 'no'} · merge state: \`${s.pr.mergeable_state}\``,
    `- Checks on \`${s.head}\`: ${t.passed} passed · ${t.failed.length} failed · ${t.pending.length} running`,
    ...t.failed.map((r) => `  - ❌ [${r.name}](${r.html_url}) (${r.conclusion})`),
    ...t.pending.map((r) => `  - ⏳ ${r.name}`),
    `- Unresolved review threads: ${s.open}`,
    `- Labels: ${s.labels.length ? s.labels.map((l) => `\`${l}\``).join(', ') : 'none'}`,
  ];
}

function render(s) {
  return [
    MARK, '### Latin cue record', '',
    `Latest cue: **${s.cue}** · prima-clock ${s.at} · head \`${s.head}\` · ${s.since}.`, '',
    '**State for the final review before merge**', ...stateLines(s), '',
    '**Cue log**', LOG_START,
    '| prima-clock | Call | By | Head | Source |', '|---|---|---|---|---|', ...s.rows, LOG_END, '',
    '<sub>Generated by `.github/workflows/latin-cue-record.yml`. It records only: ' +
      'no model call, no review, no seal, no merge.</sub>',
  ].join('\n');
}

const whyNot = (e) => e.status || e.message;

// What changed since the last row's head.
async function sinceLast({ github, repo, prev, head }) {
  if (!prev) return 'first cue on this PR';
  if (prev === head) return 'no new commits since the last cue';
  try {
    const { data } = await github.rest.repos.compareCommitsWithBasehead({ ...repo, basehead: `${prev}...${head}` });
    return `${data.ahead_by} commit(s) since the last cue ` +
      `([compare](https://github.com/${repo.owner}/${repo.repo}/compare/${prev}...${head}))`;
  } catch (e) {
    return `head moved from \`${prev}\` (compare unavailable: ${whyNot(e)})`;
  }
}

const THREADS_QUERY = `query($o:String!,$r:String!,$n:Int!,$a:String){
  repository(owner:$o,name:$r){ pullRequest(number:$n){
    reviewThreads(first:100,after:$a){ pageInfo{ hasNextPage endCursor } nodes{ isResolved } } } } }`;

// Count of unresolved review threads.
async function openThreads({ github, repo, number }) {
  let open = 0;
  let after = null;
  do {
    const q = await github.graphql(THREADS_QUERY, { o: repo.owner, r: repo.repo, n: number, a: after });
    const rt = q.repository.pullRequest.reviewThreads;
    open += rt.nodes.filter((t) => !t.isResolved).length;
    after = rt.pageInfo.hasNextPage ? rt.pageInfo.endCursor : null;
  } while (after);
  return open;
}

// Prima Recensio is the first witness, logged by the event itself.
function fromPr(payload) {
  const pr = payload.pull_request;
  const how = payload.action === 'opened' ? 'opened ready' : 'ready for review';
  return { cue: 'Prima Recensio', by: payload.sender.login, source: `[${how}](${pr.html_url})`, at: new Date(), number: pr.number };
}

function fromComment(payload) {
  const c = payload.comment;
  const names = cueNames(c.body, c.user.type, c.author_association);
  if (!names.length) return null;
  return { cue: names.join(' · '), by: c.user.login, source: `[comment](${c.html_url})`, at: c.created_at, number: payload.issue.number };
}

async function snapshot({ github, repo, number }) {
  const { data: pr } = await github.rest.pulls.get({ ...repo, pull_number: number });
  const runs = await github.paginate(github.rest.checks.listForRef, { ...repo, ref: pr.head.sha, per_page: 100 });
  const open = await openThreads({ github, repo, number });
  return { pr, head: pr.head.sha.slice(0, 7), full: pr.head.sha, tally: tally(runs), open, labels: pr.labels.map((l) => l.name) };
}

async function upsert({ github, repo, number, mine, body }) {
  if (mine) await github.rest.issues.updateComment({ ...repo, comment_id: mine.id, body });
  else await github.rest.issues.createComment({ ...repo, issue_number: number, body });
}

const callFrom = (payload) => (payload.pull_request ? fromPr(payload) : fromComment(payload));
const isMine = (c) => c.user.type === 'Bot' && String(c.body).startsWith(MARK);

// The record comment already on the PR, or undefined.
async function findMine({ github, repo, number }) {
  const all = await github.paginate(github.rest.issues.listComments, { ...repo, issue_number: number, per_page: 100 });
  return all.find(isMine);
}

async function run({ github, context, core }) {
  const call = callFrom(context.payload);
  if (!call) { core.info('No Latin call outside quotes; nothing to record.'); return; }
  const repo = context.repo;
  const snap = await snapshot({ github, repo, number: call.number });
  const mine = await findMine({ github, repo, number: call.number });
  const rows = oldRows(mine && mine.body);
  const since = await sinceLast({ github, repo, prev: lastSha(rows), head: snap.full });
  rows.push(rowFor({ ...call, head: snap.head }));
  const body = render({ ...snap, ...call, at: stamp(call.at), since, rows });
  await upsert({ github, repo, number: call.number, mine, body });
  core.info(`Recorded "${call.cue}" on ${snap.head}.`);
}

module.exports = { MARK, cueNames, stamp, oldRows, lastSha, rowFor, tally, isReady, render, run };
